[{"type":"text","text":"# DSH web 分离式重启脚本 — 由 CIM 拉起的独立进程执行，不依赖当前会话存活
# 日志: C:\Users\Administrator\.dsh\web-restart.log
$log = 'C:\Users\Administrator\.dsh\web-restart.log'
function Log($m) { Add-Content -Path $log -Value ("[" + (Get-Date -Format 'HH:mm:ss') + "] " + $m) }

Log "restart script started (detached via CIM)"
try {
  # 1) 杀旧 web 进程（PID 动态发现，端口 3080 监听者）
  $conns = Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction SilentlyContinue
  if ($conns) {
    foreach ($c in $conns) {
      Log ("killing web pid " + $c.OwningProcess)
      Stop-Process -Id $c.OwningProcess -Force -ErrorAction Stop
    }
  } else {
    Log "no listener on 3080 (already dead?)"
  }
} catch {
  Log ("kill failed: " + $_.Exception.Message)
}

# 2) 等端口释放
$deadline = (Get-Date).AddSeconds(15)
while ((Get-Date) -lt $deadline) {
  if (-not (Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction SilentlyContinue)) { break }
  Start-Sleep -Milliseconds 300
}
Log ("port 3080 free: " + (-not (Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction SilentlyContinue)))

# 3) 起新进程（分离，输出入日志）
try {
  $p = Start-Process -FilePath "cmd.exe" -ArgumentList '/c', 'node "D:\nvm\nodejs\node_modules\@deepseek-ai\dsh\lib\bin.js" web >> "C:\Users\Administrator\.dsh\web-restart.log" 2>&1' -WindowStyle Hidden -PassThru
  Log ("spawned cmd wrapper pid " + $p.Id)
} catch {
  Log ("spawn failed: " + $_.Exception.Message)
}

# 4) 等端口监听（最多 60s）
$deadline = (Get-Date).AddSeconds(60)
$up = $false
while ((Get-Date) -lt $deadline) {
  if (Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction SilentlyContinue) { $up = $true; break }
  Start-Sleep -Milliseconds 300
}
Log ("web up: " + $up)
Log "restart script done"

"}]
